require __DIR__.'/bootstrap.php';$u=require_login();$id=(int)($_GET['id']??0);$q=$db->prepare('SELECT d.*,a.creado_por_id FROM documentos d JOIN acuerdos a ON a.id=d.acuerdo_id WHERE d.id=?');$q->execute([$id]);$doc=$q->fetch();if(!$doc||($u['role']!=='ADMIN'&&(int)$doc['creado_por_id']!==$u['id'])){http_response_code(404);exit('Documento no encontrado');}if($doc['estado']!=='DISPONIBLE'||!preg_match('/^[a-f0-9]{48}\.pdf$/',$doc['storage_key']??'')){http_response_code(409);exit('Documento aún no disponible');}$base=realpath((string)($config['DOCUMENT_OUTPUT_PATH']??''));$file=$base?realpath($base.DIRECTORY_SEPARATOR.$doc['storage_key']):false;if(!$base||!$file||!str_starts_with($file,$base.DIRECTORY_SEPARATOR)){http_response_code(404);exit('Documento no encontrado');}audit($db,$u['id'],$u['username'],'DOCUMENT_DOWNLOADED','DOCUMENTO',$id);header('Content-Type: application/pdf');header('Content-Length: '.filesize($file));header("Content-Disposition: attachment; filename*=UTF-8''".rawurlencode($doc['nombre_descarga']));header('Cache-Control: private, no-store');readfile($file);exit;
